mkdir -p /app/output && cat > /app/output/styles.css << 'EOF'
:root {
  --primary: #2f5bff;
  --primary-dark: #1f46d8;
  --accent: #ff5b6e;
  --accent-2: #16c784;
  --bg: #ffffff;
  --bg-soft: #f6f8ff;
  --text: #0f172a;
  --muted: #475569;
  --border: #e2e8f0;
  --shadow: 0 10px 30px rgba(47, 91, 255, 0.12);
  --radius: 16px;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
.container { width: min(1120px, 92%); margin: 0 auto; }
.section { padding: 80px 0; }
.section-sm { padding: 56px 0; }
.eyebrow { color: var(--primary); font-weight: 700; letter-spacing: .04em; text-transform: uppercase; font-size: .78rem; }
.h1 { font-size: clamp(2rem, 4vw, 3.4rem); line-height: 1.1; margin: .35rem 0 1rem; }
.h2 { font-size: clamp(1.6rem, 3vw, 2.5rem); line-height: 1.15; margin: .35rem 0 1rem; }
.lead { font-size: 1.08rem; color: var(--muted); max-width: 70ch; }
.btn { display: inline-flex; align-items: center; gap: .5rem; padding: .85rem 1.2rem; border-radius: 999px; font-weight: 700; border: 1px solid transparent; cursor: pointer; transition: .2s ease; }
.btn-primary { background: linear-gradient(135deg, var(--primary), #6f86ff); color: #fff; box-shadow: var(--shadow); }
.btn-primary:hover { transform: translateY(-1px); background: linear-gradient(135deg, var(--primary-dark), var(--primary)); }
.btn-ghost { border-color: var(--border); background: #fff; }
.btn-ghost:hover { border-color: var(--primary); color: var(--primary); }
.nav-wrap { position: sticky; top: 0; z-index: 50; backdrop-filter: blur(8px); background: rgba(255,255,255,.86); border-bottom: 1px solid rgba(226,232,240,.8); }
.nav { display: flex; align-items: center; justify-content: space-between; min-height: 76px; gap: 1rem; }
.brand { font-weight: 900; font-size: 1.2rem; letter-spacing: .01em; }
.brand span { color: var(--primary); }
.nav-links { display: flex; align-items: center; gap: 1rem; flex-wrap: wrap; }
.nav-links a { font-weight: 600; color: #334155; padding: .35rem .5rem; border-radius: 8px; }
.nav-links a.active, .nav-links a:hover { color: var(--primary); background: #eef2ff; }
.hero { padding: 70px 0 36px; background: radial-gradient(1200px 460px at 20% -20%, rgba(47,91,255,.12), transparent), radial-gradient(1000px 420px at 90% 10%, rgba(255,91,110,.08), transparent); }
.grid-2 { display: grid; grid-template-columns: 1.1fr .9fr; gap: 2rem; align-items: center; }
.card { background: #fff; border: 1px solid var(--border); border-radius: var(--radius); padding: 1.2rem; box-shadow: 0 4px 18px rgba(15,23,42,.05); }
.stats-bar { margin-top: 22px; background: linear-gradient(135deg, #102151, #2f5bff); color: #fff; border-radius: 18px; padding: 1rem; display: grid; grid-template-columns: repeat(3,1fr); gap: 1rem; }
.stat strong { display: block; font-size: 1.7rem; line-height: 1; }
.stat span { opacity: .88; font-size: .95rem; }
.tabs { display: flex; gap: .5rem; flex-wrap: wrap; margin-bottom: 1rem; }
.tab-btn { padding: .56rem .9rem; border: 1px solid var(--border); border-radius: 999px; background: #fff; font-weight: 700; cursor: pointer; }
.tab-btn.active { border-color: var(--primary); color: var(--primary); background: #eef2ff; }
.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fade .24s ease; }
@keyframes fade { from {opacity: .2; transform: translateY(6px);} to {opacity:1; transform:none;} }
.grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 1rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4,1fr); gap: 1rem; }
.badge { display:inline-flex; padding:.2rem .55rem; border-radius:999px; background:#ecfeff; color:#0f766e; font-size:.78rem; font-weight:700; }
.logo-grid { display:grid; grid-template-columns: repeat(6,1fr); gap: .8rem; }
.logo-item { border:1px solid var(--border); border-radius:12px; padding:.9rem; text-align:center; font-weight:700; color:#334155; background:#fff; }
.carousel { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform .32s ease; }
.slide { min-width: 100%; }
.carousel-controls { display:flex; gap:.6rem; margin-top:1rem; }
.icon-btn { width: 42px; height: 42px; border-radius: 999px; border:1px solid var(--border); background:#fff; cursor:pointer; font-size:1.1rem; }
.icon-btn:hover { border-color: var(--primary); color: var(--primary); }
.accordion-item { border:1px solid var(--border); border-radius: 12px; margin-bottom:.75rem; overflow: hidden; }
.accordion-trigger { width:100%; text-align:left; padding: 1rem; background:#fff; border:0; font-weight:700; cursor:pointer; display:flex; justify-content:space-between; }
.accordion-content { display:none; padding:0 1rem 1rem; color: var(--muted); }
.accordion-item.active .accordion-content { display:block; }
.price-grid { display:grid; grid-template-columns: repeat(3,1fr); gap:1rem; }
.price-card { border:1px solid var(--border); border-radius:16px; padding:1.2rem; }
.price-card.popular { border-color: var(--primary); box-shadow: var(--shadow); }
.footer { border-top:1px solid var(--border); padding: 40px 0; color:#64748b; }
.reveal { opacity: 0; transform: translateY(14px); transition: .45s ease; }
.reveal.show { opacity:1; transform:none; }
@media (max-width: 980px){
  .grid-2,.grid-3,.grid-4,.price-grid { grid-template-columns: 1fr; }
  .logo-grid { grid-template-columns: repeat(2,1fr); }
  .stats-bar { grid-template-columns: 1fr; }
  .nav { align-items: flex-start; padding: .75rem 0; flex-direction: column; }
}
EOF

cat > /app/output/script.js << 'EOF'
document.querySelectorAll('[data-tabs]').forEach((group) => {
  const buttons = group.querySelectorAll('[data-tab-btn]');
  const panels = group.querySelectorAll('[data-tab-panel]');
  buttons.forEach((btn) => {
    btn.addEventListener('click', () => {
      const target = btn.getAttribute('data-target');
      buttons.forEach((b) => b.classList.remove('active'));
      panels.forEach((p) => p.classList.remove('active'));
      btn.classList.add('active');
      group.querySelector(`[data-tab-panel="${target}"]`)?.classList.add('active');
    });
  });
});

document.querySelectorAll('[data-accordion]').forEach((acc) => {
  const items = acc.querySelectorAll('.accordion-item');
  items.forEach((item) => {
    item.querySelector('.accordion-trigger')?.addEventListener('click', () => {
      items.forEach((i) => i.classList.remove('active'));
      item.classList.add('active');
    });
  });
});

document.querySelectorAll('[data-carousel]').forEach((carousel) => {
  const track = carousel.querySelector('.carousel-track');
  const slides = carousel.querySelectorAll('.slide');
  let idx = 0;
  const move = () => { track.style.transform = `translateX(-${idx * 100}%)`; };
  carousel.querySelector('[data-prev]')?.addEventListener('click', () => {
    idx = (idx - 1 + slides.length) % slides.length; move();
  });
  carousel.querySelector('[data-next]')?.addEventListener('click', () => {
    idx = (idx + 1) % slides.length; move();
  });
});

const observer = new IntersectionObserver((entries)=>{
  entries.forEach((entry)=>{
    if(entry.isIntersecting) entry.target.classList.add('show');
  });
},{threshold:.12});
document.querySelectorAll('.reveal').forEach((el)=>observer.observe(el));
EOF

